            if (effect.CampaignRevisionVersionIdOption.IsSet)
                writer.WriteNumber("campaignRevisionVersionId", effect.CampaignRevisionVersionIdOption.Value.Value);

            if (effect.SelectedPriceTypeOption.IsSet)
